import axios from "axios";

const API = axios.create({
  baseURL: "http://localhost:5000",
});

// 🔐 LOGIN
export const loginUser = async (data) => {
  return await API.post("/login", data);
};

// 📊 DASHBOARD
export const getDashboard = async (token) => {
  return await API.get("/dashboard", {
    headers: { Authorization: token }
  });
};

// 📢 NOTICES
export const getNotices = async () => API.get("/notices");

export const addNotice = async (data, token) =>
  API.post("/add-notice", data, {
    headers: { Authorization: token }
  });

export const deleteNotice = async (id, token) =>
  API.delete(`/delete-notice/${id}`, {
    headers: { Authorization: token }
  });

// 📚 STUDY
export const getStudy = async () => API.get("/study");

export const addStudy = async (data, token) =>
  API.post("/add-study", data, {
    headers: { Authorization: token }
  });

// 📁 PDF UPLOAD
export const uploadPDF = async (file, token) => {
  const formData = new FormData();
  formData.append("file", file);

  return await API.post("/upload-pdf", formData, {
    headers: {
      Authorization: token,
      "Content-Type": "multipart/form-data"
    }
  });
};
